public class Main {
    public static void main(String[] args) {
        int[] values = {6, 2, 5};
        int sum = 0;
        int best = values[0];
        for (int value : values) {
            sum += value;
            if (value > best) best = value;
        }
        System.out.println(sum);
        System.out.println(best);
    }
}

